<?php require 'header.php'; $db=db_load(); if($_SERVER['REQUEST_METHOD']==='POST'){ $img=upload_image('image'); $db['blogs'][]=['id'=>make_id(),'title'=>trim(post('title')),'image'=>$img,'content'=>post('content'),'created_at'=>now_iso()]; db_save($db); redirect('blogs.php'); } ?><div class="admin-top"><h1>Blogs</h1></div><div class="form-card" style="margin-bottom:25px"><h2>Add Blog</h2><form method="post" enctype="multipart/form-data"><div class="form-grid"><div class="field full"><label>Blog Title</label><input required name="title"></div><div class="field"><label>Featured Image</label><input type="file" name="image" accept="image/*"></div><div class="field full"><label>Content</label><div class="toolbar"><button type="button" onclick="cmd('bold')"><b>B</b></button><button type="button" onclick="cmd('italic')"><i>I</i></button><button type="button" onclick="cmd('underline')"><u>U</u></button></div><div id="editor" class="rich" contenteditable="true"></div><textarea hidden name="content" id="content"></textarea></div><div class="field full"><button class="btn" type="submit" onclick="document.getElementById('content').value=document.getElementById('editor').innerHTML">Publish Blog</button></div></div></form></div><div class="table-wrap"><table><tr><th>Image</th><th>Title</th><th>Date</th><th>Action</th></tr><?php foreach(array_reverse($db['blogs']) as $b): ?><tr><td><?php if($b['image']): ?><img src="../<?=e($b['image'])?>" style="width:70px;height:45px;object-fit:cover;border-radius:6px"><?php endif; ?></td><td><?=e($b['title'])?></td><td><?=e(date_fmt($b['created_at']))?></td><td><a class="btn btn-sm btn-danger" href="blog-delete.php?id=<?=e($b['id'])?>" onclick="return confirm('Delete blog?')">Delete</a></td></tr><?php endforeach; ?></table></div><script>function cmd(c){document.execCommand(c,false,null);}</script><?php require 'footer.php'; ?>
